{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE maplemonk.beastlife_shiprocket_fact_items_current AS WITH base_current AS ( SELECT ID, picked_up_date, SPLIT(channel_order_id, \'_\')[OFFSET(0)] AS channel_order_id, zone, UPPER(status) AS order_status, A, P FROM maplemonk.Beastlife_db_orders LEFT JOIN UNNEST(SHIPMENTS) AS A LEFT JOIN UNNEST(products) AS P ), parsed AS ( SELECT ID, channel_order_id, picked_up_date, zone, order_status, TRIM(REPLACE(JSON_EXTRACT_SCALAR(A, \'$.awb\'), \'\"\', \'\')) AS awb, TRIM(REPLACE(JSON_EXTRACT_SCALAR(A, \'$.courier\'), \'\"\', \'\')) AS courier, TRIM(REPLACE(JSON_EXTRACT_SCALAR(A, \'$.status\'), \'\"\', \'\')) AS shipment_status, SAFE_CAST(JSON_VALUE(A, \'$.charges.freight_charges\') AS FLOAT64) AS shipping_charges, SAFE_CAST(JSON_VALUE(A, \'$.charges.cod_charges\') AS FLOAT64) AS cod_charges, SAFE_CAST(JSON_VALUE(A, \'$.weight\') AS FLOAT64) AS shipment_weight, JSON_EXTRACT_SCALAR(A, \'$.pickedup_timestamp\') AS raw_pickedup_timestamp, JSON_EXTRACT_SCALAR(A, \'$.pickup_scheduled_date\') AS raw_pickup_scheduled_date, JSON_EXTRACT_SCALAR(A, \'$.delivered_date\') AS raw_delivered_date, JSON_EXTRACT_SCALAR(A, \'$.rto_initiated_date\') AS raw_rto_initiated_date, JSON_EXTRACT_SCALAR(A, \'$.rto_delivered_date\') AS raw_rto_delivered_date, JSON_EXTRACT_SCALAR(A, \'$.awb_assign_date\') AS raw_awb_assign_date, COALESCE( TRIM(REPLACE(JSON_EXTRACT_SCALAR(A, \'$.rto_awb\'), \'\"\', \'\')), TRIM(REPLACE(JSON_EXTRACT_SCALAR(A, \'$.return_awb\'), \'\"\', \'\')) ) AS return_awb, TRIM(REPLACE(JSON_EXTRACT_SCALAR(P, \'$.channel_sku\'), \'\"\', \'\')) AS channel_sku, TRIM(REPLACE(JSON_EXTRACT_SCALAR(P, \'$.name\'), \'\"\', \'\')) AS product_name, SAFE_CAST(JSON_VALUE(P, \'$.quantity\') AS INT64) AS quantity, SAFE_CAST(JSON_VALUE(P, \'$.selling_price\') AS FLOAT64) AS selling_price, SAFE_CAST(JSON_VALUE(P, \'$.discount\') AS FLOAT64) AS discount, SAFE_CAST(JSON_VALUE(P, \'$.tax\') AS FLOAT64) AS tax FROM base_current ) SELECT ID, channel_order_id, zone, order_status, awb, courier, shipment_status, shipping_charges, cod_charges, shipment_weight, return_awb, channel_sku, product_name, quantity, selling_price, discount, tax, picked_up_date, DATETIME(PARSE_TIMESTAMP(\'%d %b %Y, %I:%M %p\', REPLACE(CAST(raw_pickedup_timestamp AS STRING), \'\"\', \'\')), \'Asia/Kolkata\') AS pickedup_timestamp, DATETIME(TIMESTAMP(NULLIF(REPLACE(CAST(raw_pickup_scheduled_date AS STRING), \'\"\', \'\'), \'0000-00-00 00:00:00\')), \'Asia/Kolkata\') AS pickup_scheduled_date, DATETIME(TIMESTAMP(NULLIF(REPLACE(CAST(raw_delivered_date AS STRING), \'\"\', \'\'), \'0000-00-00 00:00:00\')), \'Asia/Kolkata\') AS delivered_date, DATETIME(TIMESTAMP(NULLIF(REPLACE(CAST(raw_rto_initiated_date AS STRING), \'\"\', \'\'), \'0000-00-00 00:00:00\')), \'Asia/Kolkata\') AS rto_initiated_date, DATETIME(TIMESTAMP(NULLIF(REPLACE(CAST(raw_rto_delivered_date AS STRING), \'\"\', \'\'), \'0000-00-00 00:00:00\')), \'Asia/Kolkata\') AS rto_delivered_date, DATETIME(TIMESTAMP(NULLIF(REPLACE(CAST(raw_awb_assign_date AS STRING), \'\"\', \'\'), \'0000-00-00 00:00:00\')), \'Asia/Kolkata\') AS awb_assign_date FROM parsed QUALIFY ROW_NUMBER() OVER ( PARTITION BY ID, awb, channel_sku, raw_awb_assign_date ORDER BY ID) = 1",
                    "transaction": true
                }
            ) }}
            with sample_data as (

